patch:
diff --git a/repro/no-lonely-if-19033.js b/repro/no-lonely-if-19033.js
new file mode 100644
index 0000000..9521846
--- /dev/null
+++ b/repro/no-lonely-if-19033.js
@@ -0,0 +1,19 @@
+"use strict";
+// Usage: node repro/no-lonely-if-19033.js            (this checkout)
+//        ESLINT_PATH=<dir>/node_modules/eslint node repro/no-lonely-if-19033.js  (published release)
+const { Linter } = require(process.env.ESLINT_PATH || "../lib/api");
+const code = [
+    "/* eslint no-lonely-if: \"error\" */",
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');"
+].join("\n");
+const linter = new Linter();
+const before = linter.verify(code, {});
+const { output, fixed } = linter.verifyAndFix(code, {});
+console.log("messages:", before.map(m => `${m.line}:${m.column} ${m.ruleId} ${m.message}`));
+console.log("fixed:", fixed, "\n--- output ---\n" + output + "\n--------------");
+const run = src => { try { new Function(src)(); return "no throw (outer else unreachable)"; } catch (e) { return "throws: " + e.message; } };
+console.log("original runs:", run(code));
+console.log("fixed runs:   ", run(output));
